/**
 * generated by stackra gen from src/web.app.ts (providers),
 * src/config/{i18n,theming,consent,analytics,feature-flags,telemetry,csp}.config.ts,
 * assets/public/logo.svg, gen/i18n.ts and the app instance in app.ts — do not edit
 * Purpose: the document shell: `<html lang dir>` from the request's locale mount, the head (favicon
 *          from the logo, theme colour, the stylesheet, preconnects to the image origins the CSP
 *          allows, default meta), then the app's providers (i18n, theme, consent, analytics, flags,
 *          telemetry, then the `@App` list), and the root error boundary. Every script React
 *          Router writes carries the request's CSP nonce.
 * Boundary: config classes are resolved from the app's container (`ctx.config` in the loader,
 *           `useConfig` in components), never read as statics. The root data is the locale and
 *           its catalogues, so it revalidates only when the locale mount changes. The boundary
 *           renders; it never reports (the entries report each error once). The brand fonts are
 *           system-installed families, so nothing is preloaded.
 * Runtime: isomorphic
 */
import {
  Links,
  Meta,
  Outlet,
  Scripts,
  ScrollRestoration,
  useRouteLoaderData,
  type ShouldRevalidateFunction,
} from "react-router";
import { App } from "@stackra/app/react";
import { useConfig } from "@stackra/config/react";
import { useNonce } from "@stackra/csp/react";
import { routeContext } from "@stackra/navigation/router";
import { ColorScheme } from "@stackra/theming";
import type { Route } from "./+types/root";
import { CspConfig } from "#src/config/csp.config";
import { I18nConfig } from "#src/config/i18n.config";
import { ThemingConfig } from "#src/config/theming.config";
import { RouteError } from "#src/components/route-error";
import { loadMessages } from "#stackra/i18n";
import appStyles from "#src/styles/app.css?url";
import { app } from "./app";

/** The locale of the matched mount and its catalogues, so SSR and hydration share one `t()`. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args);
  const rtl = ctx.config(I18nConfig).rtl.includes(ctx.locale);
  const messages = await loadMessages(ctx.locale, ["web", "leads", "catalogue", "experience"]);
  return { locale: ctx.locale.value, dir: rtl ? "rtl" : "ltr", messages } as const;
}

/** The mount a path belongs to: a prefixed locale's code, or the default locale's. */
function mountOf(url: URL): string {
  const i18n = app.container.resolve(I18nConfig);
  const prefixed = i18n.locales.find(
    (locale) =>
      locale !== i18n.defaultLocale &&
      (url.pathname === `/${locale.value}` || url.pathname.startsWith(`/${locale.value}/`)),
  );
  return (prefixed ?? i18n.defaultLocale).value;
}

/** The root data depends on the locale alone; a navigation or a submit inside a mount keeps it. */
export const shouldRevalidate: ShouldRevalidateFunction = ({ currentUrl, nextUrl }) =>
  mountOf(currentUrl) !== mountOf(nextUrl);

export const links: Route.LinksFunction = () => [
  { rel: "icon", href: "/favicon.svg", type: "image/svg+xml" }, // from theming.config.ts logo
  ...app.container
    .resolve(CspConfig)
    .extraImgSrc.map((origin) => ({ rel: "preconnect", href: origin, crossOrigin: "anonymous" })),
  { rel: "stylesheet", href: appStyles },
];

/**
 * Renders on success and on error alike, so the error page still has lang, dir, styles and
 * providers.
 */
export function Layout({ children }: { children: React.ReactNode }) {
  const theming = useConfig(ThemingConfig);
  const i18n = useConfig(I18nConfig);
  const nonce = useNonce();
  const root = useRouteLoaderData<typeof loader>("root");
  const scheme =
    theming.defaultScheme === ColorScheme.System ? undefined : theming.defaultScheme.value;
  return (
    <html
      lang={root?.locale ?? i18n.defaultLocale.value}
      dir={root?.dir ?? "ltr"}
      data-theme={scheme}
    >
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta
          name="theme-color"
          media="(prefers-color-scheme: light)"
          content={theming.themeColor.light}
        />
        <meta
          name="theme-color"
          media="(prefers-color-scheme: dark)"
          content={theming.themeColor.dark}
        />
        <Meta />
        <Links />
      </head>
      <body className="bg-background text-ink">
        {children}
        <ScrollRestoration nonce={nonce} />
        <Scripts nonce={nonce} />
      </body>
    </html>
  );
}

/**
 * The app's providers in order: i18n → theme → consent → analytics (gated by consent) → flags →
 * the `@App` list.
 */
export default function Root({ loaderData }: Route.ComponentProps) {
  return (
    <App app={app} locale={loaderData.locale} messages={loaderData.messages}>
      <Outlet />
    </App>
  );
}

/**
 * A thrown Response reaches the site layout's boundary first; this one catches what happens above
 * it. It only renders: the server entry and the client entry have already reported the error.
 */
export function ErrorBoundary() {
  return <RouteError />;
}
